local obj={}

local spoonPath = debug.getinfo(1, "S").source:match("@(.*/)")
local log = hs.logger.new('HotKeys', 'info')
local notify = require("notify")

obj.actions = dofile(spoonPath .. "actions.lua")

function obj:register(name, fn)
    self.actions.register(name, fn)
end

-- name → bundle ID, generated by docs/keyboard/tools/gen_bundle_ids.py
local bundleIds = dofile(spoonPath .. "app_bundle_ids.lua")
obj.bundleIds = bundleIds

local constants = require("constants")

local function getApp(name)
    local id = bundleIds[name]
    if id then
        local apps = hs.application.applicationsForBundleID(id)
        return apps and apps[1]  -- nil = not running; exact, so no fuzzy fallback
    end
    local found = hs.application.find(name)  -- fuzzy: scans app names, then window titles
    if found and tostring(found):match("hs.window:") then
        return found:application()
    end
    return found
end

local function unminimize_if_needed(app)
    if not app then return false end
    if app.isHidden and app:isHidden() then app:unhide() end
    local hasVisible = false
    for _, win in ipairs(app:allWindows() or {}) do
        if win:isStandard() and not win:isMinimized() then
            hasVisible = true
            break
        end
    end
    if not hasVisible then
        local unminimized = false
        for _, win in ipairs(app:allWindows() or {}) do
            if win:isMinimized() then
                win:unminimize()
                unminimized = true
            end
        end
        return unminimized
    end
    return true
end

obj.unminimizeIfNeeded = unminimize_if_needed

local buttonFiles = {
    "tilde",
    "1", "2", "3", "4", "5", "6", "7", "8", "9", "0",
    "minus", "equal", "backspace",
    "tab",
    "q", "w", "e", "r", "t", "y", "u", "i", "o", "p",
