local appSpecificHelper = dofile(spoonPath .. "app_specific_hotkeys.lua")

local ksheetShown = false
local hideKSheetShortCut = nil

local function registerBuiltins(register)
    local pw = function(method) return function() spoon.PowerWindows[method](spoon.PowerWindows) end end
    register("window.left", pw("left"))
    register("window.right", pw("right"))
    register("window.fullscreen", pw("fullscreen"))
    register("window.set_all_to_default", pw("arrangeAll"))
    register("window.half_left", pw("halfLeft"))
    register("window.half_right", pw("halfRight"))
    register("window.top_60", pw("top60"))
    register("window.bottom_40", pw("bottom40"))
    register("window.center", pw("center"))
    register("window.minimize_and_focus_next", pw("minimizeAndFocusNext"))
    register("window.swap_sides", pw("swapSides"))
    register("window.hide_current", pw("minimizeCurrent"))
    register("window.screen_prev", function() spoon.PowerWindows:moveToScreen("prev") end)
    register("window.screen_next", function() spoon.PowerWindows:moveToScreen("next") end)
    register("set_secondary_layout", function() hs.keycodes.setLayout(constants.LAYOUT_SECONDARY) end)
    register("set_primary_layout", function() hs.keycodes.setLayout(constants.LAYOUT_PRIMARY) end)
    register("hammerspoon_reload", function() hs.reload() end)
    register("press_return", function() hs.eventtap.keyStroke({}, "return") end)
    register("paste_bypass", function()
        local contents = hs.pasteboard.getContents()
        if not contents then return end
        if #contents > 10000 then
            hs.alert.show("Clipboard too large (" .. #contents .. " chars)", 2)
            return
        end
        hs.eventtap.keyStrokes(contents)
    end)
    register("info.show_shortcuts", function()
        if ksheetShown then
            spoon.KSheet:hide()
            if hideKSheetShortCut then hideKSheetShortCut:disable() end
        else
            if hideKSheetShortCut then hideKSheetShortCut:enable() end
            spoon.KSheet:show()
        end
        ksheetShown = not ksheetShown
    end)
end

function obj:init()
    hideKSheetShortCut = hs.hotkey.new({}, "escape", function()
        spoon.KSheet:hide()
        ksheetShown = false
        hideKSheetShortCut:disable()
    end)
    registerBuiltins(self.actions.register)
    appSpecificHelper.init(appSpecificHotkeys)
end

local function bindApp(bind, modifiers, key, appName)
    bind(modifiers, key, function()
        log.d("Hotkey triggered: " .. table.concat(modifiers, "+") .. "+" .. key .. " → " .. appName)
        local app = getApp(appName)
        if not app or (app and app.isHidden and app:isHidden()) then
            hs.application.launchOrFocus(appName)
            hs.timer.doAfter(0.15, function() unminimize_if_needed(getApp(appName)) end)
        elseif hs.application.frontmostApplication() ~= app then
            if not unminimize_if_needed(app) then
                hs.application.launchOrFocus(appName)
            else
                app:activate()
            end
        else
            local hasVisibleWindow = false
            for _, win in ipairs(app:allWindows() or {}) do
                if win:isVisible() then hasVisibleWindow = true break end
            end
            if hasVisibleWindow then
                if app.hide then app:hide() end
            elseif not unminimize_if_needed(app) then
                hs.application.launchOrFocus(appName)
            end
        end
    end)
end

-- bind(mods, key, fn) defaults to hs.hotkey.bind; tests pass a recorder.
function obj.bindChords(chords, bind)
    bind = bind or hs.hotkey.bind
    local report = { bound = 0, missing = {} }
    for _, entry in ipairs(chords) do
        if entry.chord then
            local modifiers, key = parseChord(entry.chord)
            if entry.fn then
                local action = obj.actions.get(entry.fn)
                if action then
                    bind(modifiers, key, action)
                    report.bound = report.bound + 1
                else
                    table.insert(report.missing, { chord = entry.chord, fn = entry.fn })
                end
            elseif entry.app then
                bindApp(bind, modifiers, key, entry.app)
                report.bound = report.bound + 1
            elseif entry.sendKey then
                bind(modifiers, key, function() hs.eventtap.keyStrokes(entry.sendKey) end)
                report.bound = report.bound + 1
            end
            if entry.window_default_position and entry.app then
                local slot = ({ right = "side", bottom = "corner" })[entry.window_default_position]
                local bundle = assert(entry.bundle or bundleIds[entry.app],
                    "window_default_position: no bundle ID for " .. entry.app .. " (run gen_bundle_ids.py)")
                spoon.PowerWindows:setOverride(bundle, assert(slot, entry.window_default_position))
            end
        end
    end
    return report
end

local started = false

function obj:start()
    if started then
        log.w("start() called twice; ignoring")
        return self
    end
    started = true
    local report = obj.bindChords(allChords, hs.hotkey.bind)
    obj.chords, obj.report = allChords, report   -- dotfiles_tests reads them back
    log.i("bound " .. report.bound .. " chords")
    if #report.missing > 0 then
        local lines = {}
        for _, m in ipairs(report.missing) do
            table.insert(lines, m.chord .. " → " .. m.fn)
            log.e("no action registered for fn '" .. m.fn .. "' (chord " .. m.chord .. ")")
        end
        notify.show({
            title = "HotKeys: unregistered actions",
            message = table.concat(lines, "\n"),
            symbol = "exclamationmark.triangle.fill",
            tint = "red",
            duration = 10,
        })
    end
    return self
end

return obj
